        ws.onopen = () => set({ status: "connected", reconnectAttempts: 0 });
        ws.onmessage = (e) => {
            const data = JSON.parse(e.data);
            set(s => ({ lastMessage: data, messages: [...s.messages.slice(-99), data] }));
