        ws.onclose = () => {
            set(s => ({ status: "disconnected", reconnectAttempts: s.reconnectAttempts + 1 }));
            setTimeout(() => get().connect(url), Math.min(1000 * Math.pow(2, get().reconnectAttempts), 30000));
        };
