import { create } from "zustand";
import { persist } from "zustand/middleware";

type OnboardingState = "welcome" | "profile" | "wallet" | "verification" | "complete";
const transitions: Record<OnboardingState, OnboardingState[]> = {
    welcome: ["profile"],
    profile: ["wallet"],
    wallet: ["verification"],
    verification: ["complete"],
    complete: []
};

interface OnboardingStore {
    step: OnboardingState;
    data: Record<string, any>;
    next: () => void;
    setData: (key: string, value: any) => void;
}

export const useOnboarding = create<OnboardingStore>()(
    persist((set, get) => ({
        step: "welcome",
        data: {},
        next: () => {
            const validNext = transitions[get().step];
            if (validNext.length > 0) set({ step: validNext[0] });
        },
        setData: (key, value) => set(s => ({ data: { ...s.data, [key]: value } }))
    }), { name: "onboarding" })
);
```

